def get_unpacked_marks(
    obj: object, *, consider_mro: bool = True
) -> List[Mark]:
    """Obtain the unpacked marks that are stored on an object.

    If the object is a class and ``consider_mro`` is true, marks defined on
    base classes are included as well. Marks from base classes are ordered
    before marks defined on derived classes.
    """
    if isinstance(obj, type):
        if consider_mro:
            mark_lists = [
                base.__dict__.get("pytestmark", []) for base in reversed(obj.__mro__)
            ]
        else:
            mark_lists = [obj.__dict__.get("pytestmark", [])]

        mark_list = []
        for marks in mark_lists:
            if isinstance(marks, list):
                mark_list.extend(marks)
            else:
                mark_list.append(marks)
    else:
        mark_list = getattr(obj, "pytestmark", [])
        if not isinstance(mark_list, list):
            mark_list = [mark_list]

    return list(normalize_mark_list(mark_list))

