def get_unpacked_marks(
    obj: object, *, consider_mro: bool = True
) -> List[Mark]:
    """Obtain the unpacked marks that are stored on an object.

    If the object is a class and ``consider_mro`` is true, marks defined on
    the class and all of its bases are returned. The MRO is traversed in
    reverse order so that marks from bases are applied before marks from the
    derived class.
    """
    if isinstance(obj, type):
        if consider_mro:
            mark_lists = [
                cls.__dict__.get("pytestmark", []) for cls in reversed(obj.__mro__)
            ]
        else:
            mark_lists = [obj.__dict__.get("pytestmark", [])]

        mark_list = []
        for item in mark_lists:
            if isinstance(item, list):
                mark_list.extend(item)
            else:
                mark_list.append(item)
    else:
        mark_list = getattr(obj, "pytestmark", [])
        if not isinstance(mark_list, list):
            mark_list = [mark_list]

    return list(normalize_mark_list(mark_list))

